'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);

const N = Number(input[0]);
const M = Number(input[1]);
const grid = input.slice(2, 2 + N).map(row => row.split(''));

for (let i = 0; i < N; i++) {
  if (i > 0) {
    for (let j = 0; j < M; j++) {
      if (grid[i][j] === '.' && grid[i - 1][j] === 'o') {
        grid[i][j] = 'o';
      }
    }
  }

  const queue = [];
  for (let j = 0; j < M; j++) {
    if (grid[i][j] === 'o') queue.push(j);
  }

  for (let head = 0; head < queue.length; head++) {
    const j = queue[head];
    if (i + 1 >= N || grid[i + 1][j] !== '#') continue;

    for (const next of [j - 1, j + 1]) {
      if (next >= 0 && next < M && grid[i][next] === '.') {
        grid[i][next] = 'o';
        queue.push(next);
      }
    }
  }
}

process.stdout.write(grid.map(row => row.join('')).join('\n') + '\n');
